-- NEPost initial schema (Phase 1).
--
-- The whole data model is created up front so later phases only add behaviour, not
-- table rewrites. Conventions:
--   * ids are TEXT UUIDs generated by the backend (stable across export/import);
--   * timestamps are INTEGER milliseconds since the Unix epoch (UTC);
--   * JSON columns hold typed DTOs serialised by the backend;
--   * secrets never live here: a secret value is stored in the OS credential manager and the
--     row keeps only `secret_ref` (the credential's key);
--   * foreign keys are enforced per connection (see database/mod.rs), not here.

CREATE TABLE settings (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,             -- JSON
    updated_at INTEGER NOT NULL
);

CREATE TABLE workspaces (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    sort_order  INTEGER NOT NULL DEFAULT 0,
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL
);

CREATE TABLE collections (
    id           TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    description  TEXT NOT NULL DEFAULT '',
    auth         TEXT NOT NULL DEFAULT 'null',   -- JSON auth config (secret parts by reference)
    sort_order   INTEGER NOT NULL DEFAULT 0,
    created_at   INTEGER NOT NULL,
    updated_at   INTEGER NOT NULL
);
CREATE INDEX collections_workspace ON collections(workspace_id, sort_order);

CREATE TABLE folders (
    id            TEXT PRIMARY KEY,
    collection_id TEXT NOT NULL REFERENCES collections(id) ON DELETE CASCADE,
    parent_id     TEXT REFERENCES folders(id) ON DELETE CASCADE,
    name          TEXT NOT NULL,
    description   TEXT NOT NULL DEFAULT '',
    auth          TEXT NOT NULL DEFAULT 'null',
    sort_order    INTEGER NOT NULL DEFAULT 0,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL
);
CREATE INDEX folders_collection ON folders(collection_id, parent_id, sort_order);

CREATE TABLE requests (
    id            TEXT PRIMARY KEY,
    collection_id TEXT REFERENCES collections(id) ON DELETE CASCADE,
    folder_id     TEXT REFERENCES folders(id) ON DELETE CASCADE,
    name          TEXT NOT NULL,
    description   TEXT NOT NULL DEFAULT '',
    protocol      TEXT NOT NULL DEFAULT 'http',  -- http | websocket | sse | graphql | grpc
    method        TEXT NOT NULL DEFAULT 'GET',
    url           TEXT NOT NULL DEFAULT '',
    definition    TEXT NOT NULL DEFAULT '{}',    -- JSON: params, headers, body, auth, options
    favorite      INTEGER NOT NULL DEFAULT 0,
    sort_order    INTEGER NOT NULL DEFAULT 0,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL
);
CREATE INDEX requests_parent ON requests(collection_id, folder_id, sort_order);
CREATE INDEX requests_favorite ON requests(favorite) WHERE favorite = 1;

CREATE TABLE environments (
    id           TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    is_active    INTEGER NOT NULL DEFAULT 0,
    sort_order   INTEGER NOT NULL DEFAULT 0,
    created_at   INTEGER NOT NULL,
    updated_at   INTEGER NOT NULL
);
CREATE INDEX environments_workspace ON environments(workspace_id, sort_order);

-- Variables at every scope. Exactly one owner column is set, matching `scope`.
CREATE TABLE environment_variables (
    id             TEXT PRIMARY KEY,
    scope          TEXT NOT NULL CHECK (scope IN ('global', 'workspace', 'environment', 'collection', 'folder', 'request')),
    workspace_id   TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
    environment_id TEXT REFERENCES environments(id) ON DELETE CASCADE,
    collection_id  TEXT REFERENCES collections(id) ON DELETE CASCADE,
    folder_id      TEXT REFERENCES folders(id) ON DELETE CASCADE,
    request_id     TEXT REFERENCES requests(id) ON DELETE CASCADE,
    name           TEXT NOT NULL,
    value          TEXT,                         -- NULL when secret
    is_secret      INTEGER NOT NULL DEFAULT 0,
    secret_ref     TEXT,                         -- OS credential key when secret
    enabled        INTEGER NOT NULL DEFAULT 1,
    sort_order     INTEGER NOT NULL DEFAULT 0,
    created_at     INTEGER NOT NULL,
    updated_at     INTEGER NOT NULL,
    CHECK (is_secret = 0 OR value IS NULL)
);
CREATE INDEX environment_variables_owner ON environment_variables(scope, workspace_id, environment_id, collection_id, folder_id, request_id);

-- Sent requests. Stored already redacted (no auth headers, tokens or cookies).
CREATE TABLE request_history (
    id          TEXT PRIMARY KEY,
    request_id  TEXT REFERENCES requests(id) ON DELETE SET NULL,
    workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
    method      TEXT NOT NULL,
    url         TEXT NOT NULL,
    snapshot    TEXT NOT NULL DEFAULT '{}',      -- JSON, redacted
    sent_at     INTEGER NOT NULL
);
CREATE INDEX request_history_sent ON request_history(sent_at DESC);

CREATE TABLE response_metadata (
    id           TEXT PRIMARY KEY,
    history_id   TEXT NOT NULL REFERENCES request_history(id) ON DELETE CASCADE,
    status       INTEGER,
    status_text  TEXT,
    duration_ms  INTEGER,
    size_bytes   INTEGER,
    headers      TEXT NOT NULL DEFAULT '[]',     -- JSON, redacted
    body_path    TEXT,                           -- large bodies live in app storage, not here
    body_preview TEXT,
    error        TEXT,
    received_at  INTEGER NOT NULL
);
CREATE INDEX response_metadata_history ON response_metadata(history_id);

CREATE TABLE cookies (
    id           TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    domain       TEXT NOT NULL,
    path         TEXT NOT NULL DEFAULT '/',
    name         TEXT NOT NULL,
    secret_ref   TEXT NOT NULL,                  -- cookie values are secrets
    expires_at   INTEGER,
    secure       INTEGER NOT NULL DEFAULT 0,
    http_only    INTEGER NOT NULL DEFAULT 0,
    same_site    TEXT,
    created_at   INTEGER NOT NULL,
    UNIQUE (workspace_id, domain, path, name)
);

CREATE TABLE scripts (
    id         TEXT PRIMARY KEY,
    owner_type TEXT NOT NULL CHECK (owner_type IN ('collection', 'folder', 'request')),
    owner_id   TEXT NOT NULL,
    phase      TEXT NOT NULL CHECK (phase IN ('pre-request', 'post-response')),
    source     TEXT NOT NULL DEFAULT '',
    updated_at INTEGER NOT NULL,
    UNIQUE (owner_type, owner_id, phase)
);

CREATE TABLE test_runs (
    id            TEXT PRIMARY KEY,
    workspace_id  TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
    collection_id TEXT REFERENCES collections(id) ON DELETE SET NULL,
    environment_id TEXT REFERENCES environments(id) ON DELETE SET NULL,
    iterations    INTEGER NOT NULL DEFAULT 1,
    status        TEXT NOT NULL,                 -- running | passed | failed | cancelled
    started_at    INTEGER NOT NULL,
    finished_at   INTEGER
);
CREATE INDEX test_runs_started ON test_runs(started_at DESC);

CREATE TABLE test_results (
    id          TEXT PRIMARY KEY,
    run_id      TEXT NOT NULL REFERENCES test_runs(id) ON DELETE CASCADE,
    request_id  TEXT REFERENCES requests(id) ON DELETE SET NULL,
    iteration   INTEGER NOT NULL DEFAULT 1,
    name        TEXT NOT NULL,
    passed      INTEGER NOT NULL,
    message     TEXT,
    duration_ms INTEGER
);
CREATE INDEX test_results_run ON test_results(run_id);

CREATE TABLE grpc_services (
    id           TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    source       TEXT NOT NULL,                  -- proto file path or reflection endpoint
    descriptor   BLOB,
    created_at   INTEGER NOT NULL
);

CREATE TABLE websocket_sessions (
    id          TEXT PRIMARY KEY,
    request_id  TEXT REFERENCES requests(id) ON DELETE CASCADE,
    url         TEXT NOT NULL,
    messages    TEXT NOT NULL DEFAULT '[]',      -- JSON message log
    opened_at   INTEGER NOT NULL,
    closed_at   INTEGER
);
